<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker']);$con->query("CREATE TABLE IF NOT EXISTS billing_records(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,service_type VARCHAR(100) NOT NULL,description VARCHAR(255) DEFAULT '',amount DECIMAL(12,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'Unpaid',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(patient_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare("INSERT INTO billing_records(patient_id,service_type,description,amount,status) VALUES(?,?,?,?,?)");$p=(int)$_POST['patient_id'];$t=trim($_POST['service_type']);$d=trim($_POST['description']);$a=(float)$_POST['amount'];$st=$_POST['status'];$s->bind_param('issds',$p,$t,$d,$a,$st);if($s->execute())$msg='Bill created.';}$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$rows=$con->query("SELECT b.*,p.patientname FROM billing_records b JOIN patient p ON p.patientid=b.patient_id ORDER BY b.id DESC LIMIT 100");$total=(float)$con->query("SELECT COALESCE(SUM(amount),0) FROM billing_records WHERE status='Paid'")->fetch_row()[0];$pending=(float)$con->query("SELECT COALESCE(SUM(amount),0) FROM billing_records WHERE status<>'Paid'")->fetch_row()[0];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Billing</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">FINANCE</span><h1>Billing & Payments</h1><p>Invoices, pharmacy/lab/room charges, payments and receipts.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="finance-cards"><div><small>Paid</small><b><?=number_format($total,2)?></b></div><div><small>Pending</small><b><?=number_format($pending,2)?></b></div><div><small>Total bills</small><b><?=$con->query("SELECT COUNT(*) FROM billing_records")->fetch_row()[0]?></b></div></div><div class="panel"><h2>Create invoice</h2><form method="post" class="form-grid"><label>Patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>"><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><label>Service<select name="service_type"><option>Consultation</option><option>Laboratory</option><option>Pharmacy</option><option>Room / Bed</option><option>Other</option></select></label><label>Description<input name="description"></label><label>Amount<input type="number" name="amount" step="0.01" min="0" required></label><label>Status<select name="status"><option>Unpaid</option><option>Partial</option><option>Paid</option></select></label><button class="primary-btn">Save invoice</button></form></div><div class="panel"><h2>Payment history</h2><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Service</th><th>Description</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['patientname'])?></td><td><?=esc($r['service_type'])?></td><td><?=esc($r['description'])?></td><td><?=number_format((float)$r['amount'],2)?></td><td><?=esc($r['status'])?></td><td><?=esc($r['created_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
